//! Slack Web API implementation.//!//! All API calls go through the host's HTTP capability, which handles//! credential injection and rate limiting. The WASM tool never sees//! the actual bot token.use crate::near::agent::host;use crate::types::*;const SLACK_API_BASE: &str = "https://slack.com/api";/// Percent-encode a string for use as a URL query parameter value.fn url_encode(s: &str) -> String {    let mut out = String::with_capacity(s.len());    for b in s.bytes() {        match b {            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {                out.push(b as char);            }            _ => {                out.push('%');                out.push(char::from(b"0123456789ABCDEF"[(b >> 4) as usize]));                out.push(char::from(b"0123456789ABCDEF"[(b & 0xf) as usize]));            }        }    }    out}/// Make a Slack API call.fn slack_api_call(method: &str, endpoint: &str, body: Option<&str>) -> Result<String, String> {    let url = format!("{}/{}", SLACK_API_BASE, endpoint);    // Content-Type header for POST requests    let headers = if body.is_some() {        r#"{"Content-Type": "application/json; charset=utf-8"}"#    } else {        "{}"    };    let body_bytes = body.map(|b| b.as_bytes().to_vec());    host::log(        host::LogLevel::Debug,        &format!("Slack API: {} {}", method, endpoint),    );    let response = host::http_request(method, &url, headers, body_bytes.as_deref(), None)?;    if response.status < 200 || response.status >= 300 {        return Err(format!(            "Slack API returned status {}: {}",            response.status,            String::from_utf8_lossy(&response.body)        ));    }    String::from_utf8(response.body).map_err(|e| format!("Invalid UTF-8 in response: {}", e))}/// Send a message to a Slack channel.